const STORIES=[{"bn": {"title": "আমাদের ছোট্ট পরিবার", "text": "একটি ছোট্ট সুন্দর পরিবারে থাকতেন বাবা Jaber, মা Sharmin, মেয়ে Soha ও Safa, আর ছেলে Hasan। তাদের ঘরটি খুব বড় ছিল না, কিন্তু ভালোবাসায় ছিল ভরা। প্রতিদিন সকালে বাবা হাসিমুখে বলতেন, “আমার পরিবারই আমার সবচেয়ে বড় সম্পদ।” সন্তানরা বাবার কথা শুনে হাসত, আর মা Sharmin ভালোবাসায় তাদের দিকে তাকিয়ে থাকতেন। তাদের কাছে সুখ মানে ছিল একসাথে থাকা।"}, "en": {"title": "Our Little Family", "text": "A beautiful little family lived together. There was Baba Jaber, Ma Sharmin, their daughters Soha and Safa, and their son Hasan. Their home was not very big, but it was filled with love. Every morning Baba smiled and said, “My family is my greatest treasure.” The children smiled when they heard him, and Ma Sharmin looked at them with love. To them, happiness meant being together."}, "es": {"title": "Nuestra Pequeña Familia", "text": "Una hermosa familia pequeña vivía junta. Estaban el padre Jaber, la madre Sharmin, sus hijas Soha y Safa, y su hijo Hasan. Su casa no era muy grande, pero estaba llena de amor. Cada mañana, papá sonreía y decía: “Mi familia es mi mayor tesoro”. Los niños sonreían al escucharlo y mamá Sharmin los miraba con amor. Para ellos, la felicidad significaba estar juntos."}}, {"bn": {"title": "মায়ের উষ্ণ হাসি", "text": "মা Sharmin ছিলেন পরিবারের হৃদয়। তিনি ভোরে উঠে সবার জন্য নাশতা বানাতেন। Soha ও Safa-কে স্কুলের জন্য প্রস্তুত করতেন এবং Hasan-এর ব্যাগ গুছিয়ে দিতেন। তারপর Jaber যখন কাজে যাওয়ার জন্য বের হতেন, মা তাকে ভালোবাসায় বিদায় দিতেন। সারাদিনের কাজ শেষে তিনি ক্লান্ত হয়ে পড়লেও সন্তানদের হাসি দেখলেই তাঁর ক্লান্তি কমে যেত। মা বলতেন, “তোমাদের হাসিই আমার শক্তি।”"}, "en": {"title": "Mother's Warm Smile", "text": "Mother Sharmin was the heart of the family. She woke up early and prepared breakfast for everyone. She helped Soha and Safa get ready for school and packed Hasan's bag. When Jaber left for work, she always said goodbye with love. Even when she was tired after a long day, seeing her children smile made her feel better. Mother said, “Your smiles are my strength.”"}, "es": {"title": "La Sonrisa Cálida de Mamá", "text": "La madre Sharmin era el corazón de la familia. Se levantaba temprano y preparaba el desayuno para todos. Ayudaba a Soha y Safa a prepararse para la escuela y preparaba la mochila de Hasan. Cuando Jaber salía a trabajar, siempre se despedía con amor. Aunque estaba cansada después de un largo día, ver sonreír a sus hijos la hacía sentirse mejor. Mamá decía: “Sus sonrisas son mi fuerza”."}}, {"bn": {"title": "বাবার দীর্ঘ দিন", "text": "Jaber প্রতিদিন অনেক পরিশ্রম করতেন। সকাল থেকে সন্ধ্যা পর্যন্ত তিনি পরিবারের জন্য কাজ করতেন। দিনের শেষে যখন তিনি ক্লান্ত হয়ে বাড়ি ফিরতেন, দরজা খোলার আগেই শিশুরা বাবার জন্য অপেক্ষা করত। দরজা খুললেই Soha, Safa আর Hasan দৌড়ে এসে বাবাকে জড়িয়ে ধরত। Hasan বলত, “বাবা, তুমি এসেছ!” তখন Jaber হাসতেন এবং বলতেন, “তোমাদের দেখলেই আমার সব ক্লান্তি চলে যায়।”"}, "en": {"title": "Baba's Long Day", "text": "Jaber worked very hard every day. From morning until evening, he worked for his family. At the end of the day, when he came home tired, the children were waiting for him. As soon as he opened the door, Soha, Safa and Hasan ran to him and hugged him. Hasan said, “Baba, you are home!” Jaber smiled and said, “When I see you, all my tiredness disappears.”"}, "es": {"title": "El Largo Día de Papá", "text": "Jaber trabajaba muy duro todos los días. Desde la mañana hasta la tarde, trabajaba para su familia. Al final del día, cuando regresaba cansado a casa, los niños ya lo estaban esperando. En cuanto abría la puerta, Soha, Safa y Hasan corrían hacia él y lo abrazaban. Hasan decía: “¡Papá, ya llegaste!”. Jaber sonreía y decía: “Cuando los veo, todo mi cansancio desaparece”."}}, {"bn": {"title": "তিনটি ছোট্ট হৃদয়", "text": "Soha ছিল শান্ত ও যত্নশীল। Safa ছিল হাসিখুশি ও কৌতূহলী। আর Hasan ছিল পরিবারের ছোট্ট দুষ্টু ছেলে। তিনজন একসাথে খেলত, গল্প করত এবং কখনো কখনো ছোটখাটো ঝগড়াও করত। কিন্তু তাদের ঝগড়া বেশিক্ষণ থাকত না। একটু পরেই তারা আবার একে অপরকে জড়িয়ে ধরত। মা-বাবা দূর থেকে তাদের দেখতেন এবং হাসতেন। Jaber বলতেন, “এই তিনটি হাসিই আমাদের ঘরের আলো।”"}, "en": {"title": "Three Little Hearts", "text": "Soha was calm and caring. Safa was cheerful and curious. Hasan was the playful little boy of the family. The three children played together, told stories and sometimes had little arguments. But their arguments never lasted long. Soon they hugged each other again. Their parents watched them and smiled. Jaber said, “These three smiles are the light of our home.”"}, "es": {"title": "Tres Pequeños Corazones", "text": "Soha era tranquila y cariñosa. Safa era alegre y curiosa. Hasan era el pequeño travieso de la familia. Los tres jugaban juntos, contaban historias y a veces tenían pequeñas discusiones. Pero sus discusiones nunca duraban mucho. Pronto se abrazaban y volvían a reír. Sus padres los miraban y sonreían. Jaber decía: “Estas tres sonrisas son la luz de nuestro hogar”."}}, {"bn": {"title": "বৃষ্টির সন্ধ্যা", "text": "এক সন্ধ্যায় বাইরে প্রচণ্ড বৃষ্টি শুরু হলো। হঠাৎ বিদ্যুৎ চলে গেল। সবাই মোমবাতির আলোয় একসাথে বসে পড়ল। Jaber পুরোনো দিনের মজার গল্প বলতে লাগলেন। Sharmin সবার জন্য গরম চা বানালেন। Soha ও Safa মায়ের পাশে বসল, আর Hasan বাবার হাত ধরে রইল। বাইরে বৃষ্টি পড়ছিল, কিন্তু ঘরের ভেতরে ছিল হাসি আর ভালোবাসা। সেদিন তারা বুঝেছিল, পরিবার একসাথে থাকলে অন্ধকারও সুন্দর হয়ে যায়।"}, "en": {"title": "A Rainy Evening", "text": "One evening, heavy rain began outside. Suddenly, the electricity went out. Everyone sat together under candlelight. Jaber told funny stories from the old days. Sharmin made warm tea. Soha and Safa sat beside their mother, while Hasan held his father's hand. Rain was falling outside, but inside the home there was laughter and love. That evening they learned that even darkness can feel beautiful when a family stays together."}, "es": {"title": "Una Tarde Lluviosa", "text": "Una tarde comenzó a llover muy fuerte. De repente, se fue la electricidad. Todos se sentaron juntos bajo la luz de las velas. Jaber contó historias divertidas de otros tiempos. Sharmin preparó té caliente. Soha y Safa se sentaron junto a su madre, mientras Hasan tomaba la mano de su padre. Afuera caía la lluvia, pero dentro había risas y amor. Esa noche aprendieron que hasta la oscuridad puede ser hermosa cuando una familia permanece unida."}}, {"bn": {"title": "Hasan-এর অসুস্থ রাত", "text": "একদিন Hasan অসুস্থ হয়ে পড়ল। তার শরীর গরম হয়ে গেল এবং সে খুব দুর্বল হয়ে গেল। মা Sharmin সারারাত তার পাশে বসে রইলেন। তিনি বারবার Hasan-এর কপালে হাত রাখলেন এবং পানি খাওয়ালেন। বাবা Jaber বারবার ঘুম থেকে উঠে ছেলের কপালে হাত রাখলেন এবং মায়ের পাশে দাঁড়ালেন। Soha আর Safa চুপচাপ দোয়া করল। তারা সবাই শুধু চাইছিল Hasan যেন দ্রুত সুস্থ হয়ে ওঠে। ভোরে Hasan চোখ খুলে মিষ্টি করে বলল, “আমি এখন ভালো আছি।” তখন সবার চোখে আনন্দের পানি এসে গেল। সেই মুহূর্তে তারা বুঝল, পরিবারের ভালোবাসার চেয়ে বড় ওষুধ পৃথিবীতে খুব কমই আছে।"}, "en": {"title": "The Night Hasan Was Sick", "text": "One day Hasan became sick. He had a fever and felt very weak. Mother Sharmin stayed beside him all night. She gently touched his forehead again and again and gave him water. Father Jaber woke up many times, placed his hand on his son's forehead and stayed beside Sharmin. Soha and Safa quietly prayed for their brother. Everyone wanted Hasan to get better. At dawn, Hasan opened his eyes and softly said, “I feel better now.” Tears of happiness filled everyone's eyes. They understood that few medicines are stronger than the love of a family."}, "es": {"title": "La Noche en Que Hasan Estuvo Enfermo", "text": "Un día Hasan se enfermó. Tenía fiebre y se sentía muy débil. La madre Sharmin permaneció a su lado toda la noche. Le tocaba suavemente la frente y le daba agua. El padre Jaber se despertó muchas veces, puso su mano sobre la frente de su hijo y permaneció junto a Sharmin. Soha y Safa rezaron en silencio por su hermano. Todos querían que Hasan mejorara. Al amanecer, Hasan abrió los ojos y dijo: “Ahora me siento mejor”. Los ojos de todos se llenaron de lágrimas de felicidad. Comprendieron que pocas medicinas son más fuertes que el amor de una familia."}}, {"bn": {"title": "পরিবারের প্রতিশ্রুতি", "text": "Hasan সুস্থ হওয়ার পর এক সন্ধ্যায় Jaber সবাইকে কাছে ডাকলেন। তিনি বললেন, “জীবনে যত কঠিন সময়ই আসুক, আমরা কখনো একে অপরকে একা ছেড়ে যাব না।” Soha বাবার হাত ধরে বলল, “আমরা সবসময় একসাথে থাকব।” Safa মায়ের কাঁধে মাথা রাখল। Hasan বলল, “আমিও সবাইকে দেখব।” Sharmin সবার দিকে তাকিয়ে হাসলেন। সেই ছোট্ট প্রতিশ্রুতি তাদের পরিবারের মনে চিরদিনের জন্য জায়গা করে নিল।"}, "en": {"title": "The Family Promise", "text": "After Hasan recovered, Jaber called everyone together. He said, “No matter how difficult life becomes, we will never leave each other alone.” Soha held her father's hand and said, “We will always stay together.” Safa rested her head on her mother's shoulder. Hasan said, “I will take care of everyone too.” Sharmin looked at them and smiled. That little promise stayed in their family's hearts forever."}, "es": {"title": "La Promesa de la Familia", "text": "Después de que Hasan se recuperó, Jaber reunió a todos. Dijo: “No importa lo difícil que sea la vida, nunca nos dejaremos solos”. Soha tomó la mano de su padre y dijo: “Siempre estaremos juntos”. Safa apoyó la cabeza en el hombro de su madre. Hasan dijo: “Yo también cuidaré de todos”. Sharmin los miró y sonrió. Aquella pequeña promesa permaneció para siempre en el corazón de la familia."}}, {"bn": {"title": "একসাথে বড় হওয়া", "text": "সময় ধীরে ধীরে এগিয়ে চলল। Soha ও Safa বড় হতে লাগল। Hasan নতুন নতুন স্বপ্ন দেখতে শিখল। Jaber ও Sharmin বুঝতে পারলেন, তাদের ছোট্ট শিশুরা একদিন বড় হয়ে যাবে। তাই তারা প্রতিটি ছোট মুহূর্তকে ভালোবাসা দিয়ে ধরে রাখলেন। একটি ছবি, একটি জন্মদিন, একটি স্কুলের অনুষ্ঠান, একটি পারিবারিক রাতের খাবার—সবকিছুই তাদের কাছে মূল্যবান হয়ে উঠল। তারা জানত, সময় ফিরে আসে না, কিন্তু সুন্দর স্মৃতিগুলো হৃদয়ে থেকে যায়।"}, "en": {"title": "Growing Together", "text": "Time slowly moved forward. Soha and Safa grew older. Hasan began dreaming about his future. Jaber and Sharmin realized that their little children would one day become adults. So they treasured every small moment with love. A photograph, a birthday, a school event and a family dinner all became precious memories. They knew that time never comes back, but beautiful memories remain in the heart."}, "es": {"title": "Creciendo Juntos", "text": "El tiempo pasó lentamente. Soha y Safa crecieron. Hasan comenzó a soñar con su futuro. Jaber y Sharmin comprendieron que sus pequeños algún día serían adultos. Por eso guardaron cada pequeño momento con amor. Una fotografía, un cumpleaños, una actividad escolar y una cena familiar se convirtieron en recuerdos preciosos. Sabían que el tiempo nunca regresa, pero los recuerdos hermosos permanecen en el corazón."}}, {"bn": {"title": "আসলে যা সবচেয়ে গুরুত্বপূর্ণ", "text": "এক রাতে Jaber সন্তানদের পাশে বসে বললেন, “জীবনে টাকা-পয়সা, বড় বাড়ি আর অনেক জিনিস পাওয়া যেতে পারে। কিন্তু পরিবারের ভালোবাসা পাওয়া সবচেয়ে বড় আশীর্বাদ।” Sharmin মৃদু হেসে বললেন, “আমরা একসাথে থাকলে আমাদের ঘর সবসময় পূর্ণ থাকবে।” Soha, Safa আর Hasan বাবার কথা মন দিয়ে শুনল। তারা বুঝল, পরিবারের মূল্য কোনো টাকা দিয়ে মাপা যায় না। তারা ছিল পাঁচটি আলাদা মানুষ, কিন্তু ভালোবাসায় যেন একটি হৃদয়।"}, "en": {"title": "What Really Matters", "text": "One night Jaber sat beside the children and said, “In life, we may have money, a big house and many things. But having the love of a family is the greatest blessing.” Sharmin smiled gently and said, “As long as we are together, our home will always be full.” Soha, Safa and Hasan listened carefully. They understood that the value of a family cannot be measured by money. They were five different people, but their love made them one heart."}, "es": {"title": "Lo Que Realmente Importa", "text": "Una noche Jaber se sentó junto a los niños y dijo: “En la vida podemos tener dinero, una casa grande y muchas cosas. Pero tener el amor de una familia es la mayor bendición”. Sharmin sonrió y dijo: “Mientras estemos juntos, nuestro hogar siempre estará lleno”. Soha, Safa y Hasan escucharon atentamente. Comprendieron que el valor de una familia no puede medirse con dinero. Eran cinco personas diferentes, pero su amor los hacía un solo corazón."}}, {"bn": {"title": "চিরদিন একসাথে", "text": "রাত শেষে সবাই একে অপরকে জড়িয়ে ধরল। বাবা Jaber বললেন, “তোমরা আমার জীবনের সবচেয়ে সুন্দর গল্প।” মা Sharmin বললেন, “তোমরাই আমার পৃথিবী।” Soha, Safa ও Hasan একসাথে বলল, “আমরা আমাদের পরিবারকে খুব ভালোবাসি।” বাইরে রাত ছিল শান্ত। আকাশে তারা জ্বলছিল। আর ছোট্ট সেই ঘরের ভেতরে ছিল এমন এক ভালোবাসা, যা কোনো গল্পের শেষেও শেষ হয় না। কারণ সত্যিকারের পরিবারের ভালোবাসার কোনো শেষ নেই। যতদিন তারা একে অপরকে মনে রাখবে, ততদিন সেই ভালোবাসার গল্প চলতেই থাকবে।"}, "en": {"title": "Forever Together", "text": "At the end of the night, everyone hugged one another. Baba Jaber said, “You are the most beautiful story of my life.” Mother Sharmin said, “You are my whole world.” Soha, Safa and Hasan said together, “We love our family so much.” Outside, the night was peaceful and the stars were shining. Inside that little home was a love that could never end. Because true family love has no ending. As long as they remember one another, their story of love will continue forever."}, "es": {"title": "Juntos Para Siempre", "text": "Al final de la noche, todos se abrazaron. Papá Jaber dijo: “Ustedes son la historia más hermosa de mi vida”. La madre Sharmin dijo: “Ustedes son mi mundo entero”. Soha, Safa y Hasan dijeron juntos: “Amamos muchísimo a nuestra familia”. Afuera, la noche estaba tranquila y las estrellas brillaban. Dentro de aquella pequeña casa había un amor que nunca podría terminar. Porque el verdadero amor de una familia no tiene final. Mientras se recuerden unos a otros, su historia de amor continuará para siempre."}}];
let page=0,lang='bn',full=false,stopped=false;
const $=id=>document.getElementById(id);
function render(){
 const s=STORIES[page][lang]; $('label').textContent=`STORY ${page+1} OF ${STORIES.length}`; $('title').textContent=s.title; $('text').textContent=s.text; $('count').textContent=`${page+1} / ${STORIES.length}`; $('bar').style.width=((page+1)/STORIES.length*100)+'%';
}
function voiceFor(code){
 const vs=speechSynthesis.getVoices(); const exact=vs.find(v=>v.lang.toLowerCase()===code.toLowerCase()); if(exact)return exact; const p=code.split('-')[0].toLowerCase(); return vs.find(v=>v.lang.toLowerCase().startsWith(p))||null;
}
let sentenceQueue = [];
let sentenceIndex = 0;

// Character animation helpers. These must exist before speech starts.
function stopCharacterAnimation() {
  document.querySelectorAll("[data-character]").forEach(el => el.classList.remove("speaking"));
}

function animateCharacterForSentence(sentence) {
  stopCharacterAnimation();
  const t = String(sentence || "").toLowerCase();
  let character = "dad";
  if (t.includes("hasan")) character = "hasan";
  else if (t.includes("soha")) character = "soha";
  else if (t.includes("safa")) character = "safa";
  else if (t.includes("sharmin") || t.includes("মা")) character = "mom";
  else if (t.includes("jaber") || t.includes("বাবা")) character = "dad";
  const el = document.querySelector(`[data-character="${character}"]`);
  if (el) el.classList.add("speaking");
}

// Make browser voices available before the first speech request.
if ("speechSynthesis" in window) {
  speechSynthesis.getVoices();
  speechSynthesis.onvoiceschanged = () => speechSynthesis.getVoices();
}

function getSentences(text) {
  // Bengali punctuation + English punctuation.
  // Keep each sentence as a separate utterance so long Bengali text
  // does not get silently dropped by browser speech synthesis.
  return text
    .replace(/\r/g, " ")
    .split(/(?<=[।!?])\s+|(?<=[.!?])\s+/)
    .map(x => x.trim())
    .filter(Boolean);
}

function speak(i, all) {
  if (stopped) return;

  page = i;
  render();

  const story = STORIES[i][lang];
  sentenceQueue = getSentences(story.title + ". " + story.text);
  sentenceIndex = 0;

  full = all;
  speakNextSentence(i, all);
}

function speakNextSentence(i, all) {
  if (stopped) return;

  if (sentenceIndex >= sentenceQueue.length) {
    if (all && i < STORIES.length - 1) {
      setTimeout(() => speak(i + 1, true), 650);
    } else {
      full = false;
      $("status").textContent =
        i === STORIES.length - 1
          ? "❤️ All 10 stories finished!"
          : "✅ This complete story is finished — press Next for the next story.";
    }
    return;
  }

  const sentence = sentenceQueue[sentenceIndex];
  animateCharacterForSentence(sentence);

  const u = new SpeechSynthesisUtterance(sentence);

  if (lang === "bn") {
    u.lang = "bn-BD";
    u.rate = 0.78;
    u.pitch = 1.04;
  } else if (lang === "en") {
    u.lang = "en-US";
    u.rate = 0.86;
    u.pitch = 1.03;
  } else {
    u.lang = "es-ES";
    u.rate = 0.84;
    u.pitch = 1.03;
  }

  const voices = speechSynthesis.getVoices();
  const exact = voices.find(
    v => v.lang.toLowerCase() === u.lang.toLowerCase()
  );

  const prefix = u.lang.split("-")[0].toLowerCase();

  const matching = voices.find(
    v => v.lang.toLowerCase().startsWith(prefix)
  );

  if (exact) {
    u.voice = exact;
  } else if (matching) {
    u.voice = matching;
  }

  $("status").textContent =
    `🔊 Reading Story ${i + 1} of 10 — ` +
    `${lang === "bn" ? "Bangla" : lang === "en" ? "English" : "Spanish"}`;

  u.onend = () => {
    stopCharacterAnimation();
    if (stopped) return;

    sentenceIndex++;

    setTimeout(() => {
      speakNextSentence(i, all);
    }, lang === "bn" ? 180 : 120);
  };

  u.onerror = () => {
    stopCharacterAnimation();
    if (stopped) return;

    // Retry the same sentence once using the browser's default voice.
    const retry = new SpeechSynthesisUtterance(sentence);
    retry.lang = u.lang;
    retry.rate = u.rate;
    retry.pitch = u.pitch;
    retry.volume = 1;

    retry.onend = () => {
      if (stopped) return;
      sentenceIndex++;
      setTimeout(() => speakNextSentence(i, all), 180);
    };

    speechSynthesis.cancel();
    setTimeout(() => speechSynthesis.speak(retry), 150);
  };

  speechSynthesis.cancel();
  setTimeout(() => {
    if (!stopped) speechSynthesis.speak(u);
  }, 80);
}

$('language').onchange=e=>{lang=e.target.value;stop();render();$('status').textContent='🌎 Language changed';};
$('listen').onclick=()=>{stopped=false;full=false;speak(page,false);};
$('full').onclick=()=>{stopped=false;full=true;speak(0,true);};
function stop(){stopped=true;full=false;speechSynthesis.cancel();stopCharacterAnimation();}
$('stop').onclick=()=>{stop();$('status').textContent='⏹ Stopped';};
$('next').onclick=()=>{stop();if(page<9){page++;render();$('status').textContent='📖 Press Listen This Story';}};
$('prev').onclick=()=>{stop();if(page>0){page--;render();$('status').textContent='📖 Press Listen This Story';}};
render();
/* ==========================================
   FAMILY CLAP SOUND + PERIODIC CLAP ANIMATION
   ========================================== */
let audioCtx = null;
let clapTimer = null;
let clapTimeout = null;

function ensureAudio(){
  try{
    if(!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if(audioCtx.state === 'suspended') audioCtx.resume();
  }catch(e){}
}

function clapSound(){
  ensureAudio();
  if(!audioCtx) return;
  const now = audioCtx.currentTime;
  // Two very short soft claps: a noise burst + filtered transient.
  [0, 0.105].forEach((delay, idx)=>{
    const duration = 0.075;
    const buffer = audioCtx.createBuffer(1, Math.floor(audioCtx.sampleRate*duration), audioCtx.sampleRate);
    const data = buffer.getChannelData(0);
    for(let i=0;i<data.length;i++){
      const env = Math.pow(1-i/data.length, 2.4);
      data[i] = (Math.random()*2-1) * env * 0.7;
    }
    const src = audioCtx.createBufferSource();
    const filter = audioCtx.createBiquadFilter();
    const gain = audioCtx.createGain();
    filter.type='bandpass';
    filter.frequency.value = idx ? 1800 : 1500;
    filter.Q.value = 0.9;
    gain.gain.setValueAtTime(0.0001, now+delay);
    gain.gain.exponentialRampToValueAtTime(0.16, now+delay+0.006);
    gain.gain.exponentialRampToValueAtTime(0.0001, now+delay+duration);
    src.buffer=buffer;
    src.connect(filter).connect(gain).connect(audioCtx.destination);
    src.start(now+delay);
    src.stop(now+delay+duration+0.01);
  });
}

function setClapping(on){
  document.querySelectorAll('.photo-character').forEach(el=>el.classList.toggle('clapping', on));
}

function clapFamily(){
  if(stopped) return;
  setClapping(true);
  clapSound();
  clearTimeout(clapTimeout);
  clapTimeout=setTimeout(()=>setClapping(false), 620);
}

function startClapLoop(){
  clearInterval(clapTimer);
  clearTimeout(clapTimeout);
  ensureAudio();
  // First clap after a short delay, then every 4–6 seconds.
  const schedule=()=>{
    if(stopped) return;
    clapFamily();
    clapTimer=setTimeout(schedule, 4200 + Math.random()*1700);
  };
  clapTimer=setTimeout(schedule, 2200);
}

function stopClapLoop(){
  clearTimeout(clapTimer);
  clearTimeout(clapTimeout);
  clapTimer=null;
  clapTimeout=null;
  setClapping(false);
}

// Wrap the existing speech controls so the first user click unlocks audio.
const originalListenHandler = $('listen').onclick;
$('listen').onclick = () => { ensureAudio(); startClapLoop(); originalListenHandler(); };
const originalFullHandler = $('full').onclick;
$('full').onclick = () => { ensureAudio(); startClapLoop(); originalFullHandler(); };
const originalStopHandler = $('stop').onclick;
$('stop').onclick = () => { stopClapLoop(); originalStopHandler(); };

// Also stop clap effects whenever the existing stop() function is used by navigation.
const _oldStop = stop;
stop = function(){ stopClapLoop(); _oldStop(); };

/* ==========================================
   STORY EDITOR
   ========================================== */
const ORIGINAL_STORIES = JSON.parse(JSON.stringify(STORIES));
const editorModal = $('editorModal');
const editLanguage = $('editLanguage');
const editStorySelect = $('editStorySelect');
const editTitle = $('editTitle');
const editText = $('editText');
const editStatus = $('editStatus');

function populateStoryChoices(){
  editStorySelect.innerHTML = STORIES.map((_,i)=>`<option value="${i}">Story ${i+1}: ${STORIES[i][editLanguage.value].title}</option>`).join('');
  editStorySelect.value = String(page);
}

function loadEditorStory(){
  const i = Number(editStorySelect.value || 0);
  const s = STORIES[i][editLanguage.value];
  editTitle.value = s.title;
  editText.value = s.text;
  editStatus.textContent = '';
}

function openEditor(){
  editLanguage.value = lang;
  populateStoryChoices();
  loadEditorStory();
  editorModal.classList.add('open');
  editorModal.setAttribute('aria-hidden','false');
}

function closeEditor(){
  editorModal.classList.remove('open');
  editorModal.setAttribute('aria-hidden','true');
}

function saveEditorStory(){
  const i = Number(editStorySelect.value || 0);
  const code = editLanguage.value;
  STORIES[i][code].title = editTitle.value.trim() || STORIES[i][code].title;
  STORIES[i][code].text = editText.value.trim() || STORIES[i][code].text;
  localStorage.setItem('familyTalkingBookStories', JSON.stringify(STORIES));
  page = i;
  lang = code;
  $('language').value = code;
  render();
  editStatus.textContent = '✅ Story saved successfully.';
  populateStoryChoices();
  editStorySelect.value = String(i);
}

function resetEditorStory(){
  const i = Number(editStorySelect.value || 0);
  const code = editLanguage.value;
  STORIES[i][code] = JSON.parse(JSON.stringify(ORIGINAL_STORIES[i][code]));
  localStorage.setItem('familyTalkingBookStories', JSON.stringify(STORIES));
  loadEditorStory();
  render();
  editStatus.textContent = '↩ This story was reset.';
}

function resetAllEditorStories(){
  if(!confirm('Reset all 10 stories to the original stories?')) return;
  for(let i=0;i<STORIES.length;i++){
    for(const code of ['bn','en','es']) STORIES[i][code] = JSON.parse(JSON.stringify(ORIGINAL_STORIES[i][code]));
  }
  localStorage.removeItem('familyTalkingBookStories');
  populateStoryChoices();
  editStorySelect.value = String(page);
  loadEditorStory();
  render();
  editStatus.textContent = '♻ All stories restored.';
}

function loadSavedStories(){
  try{
    const saved = JSON.parse(localStorage.getItem('familyTalkingBookStories') || 'null');
    if(!Array.isArray(saved) || saved.length !== STORIES.length) return;
    saved.forEach((story,i)=>{
      if(story && story.bn && story.en && story.es){
        for(const code of ['bn','en','es']){
          if(typeof story[code].title === 'string') STORIES[i][code].title = story[code].title;
          if(typeof story[code].text === 'string') STORIES[i][code].text = story[code].text;
        }
      }
    });
  }catch(e){}
}

loadSavedStories();
$('editStories').onclick = openEditor;
$('closeEditor').onclick = closeEditor;
editLanguage.onchange = () => { populateStoryChoices(); loadEditorStory(); };
editStorySelect.onchange = loadEditorStory;
$('saveStory').onclick = saveEditorStory;
$('resetStory').onclick = resetEditorStory;
$('resetAll').onclick = resetAllEditorStories;
editorModal.addEventListener('click', e => { if(e.target === editorModal) closeEditor(); });
document.addEventListener('keydown', e => { if(e.key === 'Escape') closeEditor(); });

/* Keep editor language in sync with the main language selector. */
const _oldLanguageChange = $('language').onchange;
$('language').onchange = e => {
  lang = e.target.value;
  stop();
  render();
  $('status').textContent = '🌎 Language changed';
};

/* Stronger, short realistic clap: two hands meeting twice. */
const _baseClapSound = clapSound;
clapSound = function(){
  ensureAudio();
  if(!audioCtx) return;
  const now = audioCtx.currentTime;
  [0,0.115].forEach((delay,idx)=>{
    const duration=.095;
    const buffer=audioCtx.createBuffer(1,Math.floor(audioCtx.sampleRate*duration),audioCtx.sampleRate);
    const data=buffer.getChannelData(0);
    for(let i=0;i<data.length;i++){
      const t=i/data.length;
      const env=Math.pow(1-t,2.8);
      data[i]=(Math.random()*2-1)*env*.95;
    }
    const src=audioCtx.createBufferSource();
    const filter=audioCtx.createBiquadFilter();
    const gain=audioCtx.createGain();
    filter.type='bandpass';
    filter.frequency.value=idx?2100:1750;
    filter.Q.value=1.15;
    gain.gain.setValueAtTime(.0001,now+delay);
    gain.gain.exponentialRampToValueAtTime(.24,now+delay+.004);
    gain.gain.exponentialRampToValueAtTime(.0001,now+delay+duration);
    src.buffer=buffer;
    src.connect(filter).connect(gain).connect(audioCtx.destination);
    src.start(now+delay);
    src.stop(now+delay+duration+.01);
  });
};
